using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class GangDriveByTests
    {
        static readonly Action<GangState> Save=s=>{};
        static GangState State()=>new GangState{Gang="Mine",Reputation=800,Rank=3,DriveBys=new GangDriveByData{Enabled=true},Turf=new GangTurfData{Owners={{1,"Mine"},{2,"Enemy"}}}};
        static GangDriveByRun Run(string id="ambush")=>new GangDriveByRun{Id=id,Gang="Mine",Rival="Enemy",Options=new GangDriveByOptions(),Models=Enumerable.Repeat("g_m_y_famca_01",4).ToArray()};
        static GangState Begin(){Assert.True(GangDriveByTransactions.Begin(State(),Run(),Save,out var s));return s;}
        [Fact] public void LegacySaveHasNoOptInOrPendingEvent(){var s=JsonConvert.DeserializeObject<GangState>("{\"Gang\":\"Mine\",\"Future\":7}");Assert.Null(s.DriveBys);Assert.False(new GangDriveByData().Enabled);Assert.True(new GangDriveByData().Valid);}
        [Fact] public void DefaultTimingMatchesReference(){var c=new GangDriveByOptions();Assert.True(c.Valid);Assert.Equal(300,c.MinIntervalSeconds);Assert.Equal(900,c.MaxIntervalSeconds);Assert.Equal(85,c.Chance);Assert.Equal(45,c.ApproachSeconds);Assert.Equal(7500,c.ShootingMilliseconds);Assert.Equal(20,c.EscapeSeconds);Assert.Equal(35,c.ShootDistance);}
        [Fact] public void BeginTakesDeepSnapshotAndChangesOnlyOwnEventBook(){var s=State();var run=Run();int saves=0;Assert.True(GangDriveByTransactions.Begin(s,run,n=>saves++,out var n));Assert.Equal(1,saves);run.Options.ShootingMilliseconds=1000;run.Models[0]="changed";Assert.Equal(7500,n.DriveBys.Pending.Options.ShootingMilliseconds);Assert.Equal("g_m_y_famca_01",n.DriveBys.Pending.Models[0]);Assert.Null(s.DriveBys.Pending);Assert.Equal(800,n.Reputation);Assert.Equal(3,n.Rank);Assert.Equal("Mine",n.Turf.Owners[1]);Assert.Equal("Enemy",n.Turf.Owners[2]);Assert.Equal(1,n.DriveBys.Started);}
        [Fact] public void DisabledForeignOrAlreadyPendingCannotBegin(){var s=State();s.DriveBys.Enabled=false;Assert.False(GangDriveByTransactions.Begin(s,Run(),Save,out _));s=State();s.Gang="Other";Assert.False(GangDriveByTransactions.Begin(s,Run(),Save,out _));s=Begin();Assert.False(GangDriveByTransactions.Begin(s,Run("second"),Save,out _));}
        [Fact] public void AlertAndOtherActivitiesBlockNewDriveBy(){var s=State();s.Warfare=new GangWarData{AttacksEnabled=true,Alert=new GangWarAlert{Id="alert",Gang="Mine",Attacker="Enemy",Area=GangTurfOptions.Defaults().Areas[0]}};Assert.False(GangDriveByTransactions.Begin(s,Run(),Save,out _));s=State();s.Loyalty=new GangLoyaltyData{Pending=new GangLoyaltyAttempt()};Assert.False(GangDriveByTransactions.Begin(s,Run(),Save,out _));}
        [Fact] public void PendingDriveByBlocksWarSchedulingAndTerritoryBegin(){var s=Begin();Assert.False(GangWarRules.Free(s));var p=new GangTurfAttempt{Id="capture",Gang="Mine",PreviousOwner="Enemy",Area=GangTurfOptions.Defaults().Areas[1],Radius=45,SecondsLimit=600,Models=Enumerable.Repeat("g_m_y_famca_01",3).ToArray()};Assert.False(GangTurfTransactions.Begin(s,p,Save,out _));Assert.False(GangLeaderRules.CanLeave(s,"Mine"));}
        [Theory][InlineData("repelled")][InlineData("escaped")][InlineData("interrupted")][InlineData("death")]
        public void OutcomesAreRecordedWithoutOwnershipOrReputationRewards(string outcome){var s=Begin();Assert.True(GangDriveByTransactions.Finish(s,"ambush",outcome,Save,out s));Assert.Null(s.DriveBys.Pending);Assert.Equal(1,s.DriveBys.Started);Assert.Equal(1,s.DriveBys.Repelled+s.DriveBys.Escaped+s.DriveBys.Interrupted+s.DriveBys.Deaths);Assert.Equal(outcome,s.DriveBys.History.Single().Outcome);Assert.Equal("Mine",s.Turf.Owners[1]);Assert.Equal("Enemy",s.Turf.Owners[2]);Assert.Equal(800,s.Reputation);Assert.Equal(0,s.Turf.Attempts);}
        [Fact] public void FinishReplayDoesNotSaveOrIncrementAndCannotChangeOutcome(){var s=Begin();GangDriveByTransactions.Finish(s,"ambush","repelled",Save,out s);Assert.True(GangDriveByTransactions.Finish(s,"ambush","repelled",n=>throw new Exception(),out s));Assert.Equal(1,s.DriveBys.Repelled);Assert.False(GangDriveByTransactions.Finish(s,"ambush","death",Save,out _));Assert.False(GangDriveByTransactions.Begin(s,Run(),Save,out _));}
        [Fact] public void FinishCannotCloseAnotherEventOrUseUnknownOutcome(){var s=Begin();Assert.False(GangDriveByTransactions.Finish(s,"wrong","repelled",Save,out _));Assert.False(GangDriveByTransactions.Finish(s,"ambush","paid",Save,out _));Assert.NotNull(s.DriveBys.Pending);}
        [Fact] public void FailedBeginFinishAndPreferenceSaveLeaveOriginalStateUntouched(){var s=State();string before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangDriveByTransactions.Begin(s,Run(),n=>throw new Exception(),out _));Assert.Throws<Exception>(()=>GangDriveByTransactions.Configure(s,false,n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));s=Begin();before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangDriveByTransactions.Finish(s,"ambush","repelled",n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));}
        [Fact] public void ReloadedActiveEventIsRecordedInterruptedWithoutSpawningOrReward(){var s=CharacterRules.Copy(Begin());Assert.True(GangDriveByTransactions.Finish(s,"ambush","interrupted",Save,out s));Assert.Equal(1,s.DriveBys.Interrupted);Assert.Equal(0,s.DriveBys.Repelled);Assert.Equal(800,s.Reputation);Assert.Null(s.DriveBys.Pending);}
        [Fact] public void CapturedAffiliationInHistorySurvivesLeavingGangBeforeInterruption(){var s=Begin();s.Gang="Other";Assert.True(GangDriveByTransactions.Finish(s,"ambush","interrupted",Save,out s));Assert.Equal("Mine",s.DriveBys.History.Single().Gang);Assert.Equal("Other",s.Gang);}
        [Fact] public void DisablingDoesNotInventOutcomeAndAllowsExplicitClose(){var s=Begin();Assert.True(GangDriveByTransactions.Configure(s,false,Save,out s));Assert.False(s.DriveBys.Enabled);Assert.NotNull(s.DriveBys.Pending);Assert.True(GangDriveByTransactions.Finish(s,"ambush","interrupted",Save,out s));Assert.Equal(1,s.DriveBys.Interrupted);Assert.False(s.DriveBys.Enabled);}
        [Fact] public void BoundedHistoryAndUnknownFieldsRoundTrip(){var s=State();var j=JObject.FromObject(s);j["FutureRoot"]=7;j["DriveBys"]["FutureBook"]="keep";s=j.ToObject<GangState>();for(int i=0;i<40;i++){GangDriveByTransactions.Begin(s,Run("id"+i),Save,out s);GangDriveByTransactions.Finish(s,"id"+i,"escaped",Save,out s);}Assert.Equal(40,s.DriveBys.Escaped);Assert.Equal(32,s.DriveBys.History.Count);Assert.Equal("id8",s.DriveBys.History[0].Id);j=JObject.FromObject(s);Assert.Equal(7,(int)j["FutureRoot"]);Assert.Equal("keep",(string)j["DriveBys"]["FutureBook"]);}
        [Fact] public void InvalidBooksModelsAndOverflowStayProtected(){var s=State();s.DriveBys.Started=-1;Assert.False(GangDriveByTransactions.Configure(s,true,Save,out _));s=State();s.DriveBys.Started=long.MaxValue;Assert.False(GangDriveByTransactions.Begin(s,Run(),Save,out _));var r=Run();r.Models[0]="invalid/model";Assert.False(r.Valid);s=Begin();s.DriveBys.Repelled=long.MaxValue;Assert.False(s.DriveBys.Valid);Assert.False(GangDriveByTransactions.Finish(s,"ambush","repelled",Save,out _));}
        [Fact] public void CorruptCounterSumUsesDecimalWithoutLongWraparound(){var b=new GangDriveByData{Started=long.MaxValue,Repelled=long.MaxValue,Escaped=long.MaxValue};Assert.False(b.Valid);}
        static void Advance(GangDriveByClock c,int from,int until,float distance=100,bool driver=true,bool gunner=true){for(int n=from;n<=until;n+=500)c.Tick(n,true,distance,driver,gunner);}
        [Fact] public void ApproachShootingAndEscapeHaveIndependentBoundedDurations(){var c=new GangDriveByClock(new GangDriveByOptions(),0);c.Tick(0,true,100,true,true);c.Tick(500,true,35,true,true);Assert.Equal(GangDriveByStage.Shooting,c.Stage);Advance(c,1000,8000,35);Assert.Equal(GangDriveByStage.Escape,c.Stage);Advance(c,8500,28000,100);Assert.Equal(GangDriveByStage.Finished,c.Stage);Assert.False(c.Repelled);}
        [Fact] public void CannotShootBeforeThirtyFiveMetersAndApproachTimesOut(){var c=new GangDriveByClock(new GangDriveByOptions(),0);Advance(c,0,45000,36);Assert.Equal(GangDriveByStage.Escape,c.Stage);Assert.Equal(0,c.Elapsed);Assert.False(c.Repelled);}
        [Fact] public void ShootingStartedNearDeadlineCanCompleteItsOwnBurst(){var c=new GangDriveByClock(new GangDriveByOptions(),0);Advance(c,0,44000,100);c.Tick(44500,true,35,true,true);Assert.Equal(GangDriveByStage.Shooting,c.Stage);Advance(c,45000,51500,35);Assert.Equal(GangDriveByStage.Shooting,c.Stage);c.Tick(52000,true,35,true,true);Assert.Equal(GangDriveByStage.Escape,c.Stage);}
        [Fact] public void LosingGunnersBeginsRepelledEscapeAndDriverDeathFinishes(){var c=new GangDriveByClock(new GangDriveByOptions(),0);c.Tick(0,true,20,true,false);Assert.Equal(GangDriveByStage.Escape,c.Stage);Assert.True(c.Repelled);c.Tick(500,true,20,false,false);Assert.Equal(GangDriveByStage.Finished,c.Stage);}
        [Fact] public void EscapeEndsAfterTwoHundredTwentyMeters(){var c=new GangDriveByClock(new GangDriveByOptions(),0);c.Tick(0,true,100,true,false);c.Tick(500,true,220,true,false);Assert.Equal(GangDriveByStage.Escape,c.Stage);c.Tick(1000,true,220.1f,true,false);Assert.Equal(GangDriveByStage.Finished,c.Stage);}
        [Fact] public void ClockDoesNotChargePauseOrLongGapAndHandlesSignedRollover(){var c=new GangDriveByClock(new GangDriveByOptions(),0);c.Tick(0,true,100,true,true);c.Tick(10000,false,100,true,true);c.Tick(20000,true,100,true,true);Assert.Equal(0,c.Elapsed);c.Tick(30000,true,100,true,true);Assert.Equal(1000,c.Elapsed);var r=new GangDriveByClock(new GangDriveByOptions(),int.MaxValue-50);r.Tick(int.MaxValue-50,true,100,true,true);r.Tick(int.MinValue+49,true,100,true,true);Assert.Equal(100,r.Elapsed);}
        [Fact] public void ClockSnapshotsOptionsAndDoesNotRefireAfterEscape(){var opts=new GangDriveByOptions();var c=new GangDriveByClock(opts,0);opts.ShootingMilliseconds=1000;c.Tick(0,true,35,true,true);Advance(c,500,7000,35);Assert.Equal(GangDriveByStage.Shooting,c.Stage);c.Tick(7500,true,35,true,true);Assert.Equal(GangDriveByStage.Escape,c.Stage);c.Tick(8000,true,0,true,true);Assert.Equal(GangDriveByStage.Escape,c.Stage);}
        [Theory][InlineData(74,0,false)][InlineData(75,8,true)][InlineData(170,-8,true)][InlineData(171,0,false)][InlineData(100,9,false)]public void SpawnUsesSourceRoadEnvelopeAndVerticalSafety(float distance,float height,bool result)=>Assert.Equal(result,GangDriveByRules.Spawn(distance,height));
        [Theory][InlineData(40,40,false)][InlineData(40.1f,40,true)][InlineData(45,45,false)][InlineData(45.1f,45,true)]public void HqAndTerritoryBoundariesAreExcluded(float distance,float radius,bool result)=>Assert.Equal(result,GangDriveByRules.Outside(distance,radius));
        [Fact] public void InvalidDistancesAndIndoorAirWaterStatesAreExcluded(){Assert.False(GangDriveByRules.Spawn(float.NaN,0));Assert.False(GangDriveByRules.Shoot(float.PositiveInfinity,true,true,new GangDriveByOptions()));Assert.True(GangDriveByRules.Outdoor(true,true,false,false,false));Assert.False(GangDriveByRules.Outdoor(true,true,true,false,false));Assert.False(GangDriveByRules.Outdoor(true,true,false,true,false));Assert.False(GangDriveByRules.Outdoor(true,true,false,false,true));}
        [Fact] public void ConfigRejectsInvalidDurationsChanceAndModel(){Assert.False(new GangDriveByOptions{MinIntervalSeconds=0}.Valid);Assert.False(new GangDriveByOptions{MaxIntervalSeconds=299}.Valid);Assert.False(new GangDriveByOptions{Chance=101}.Valid);Assert.False(new GangDriveByOptions{ShootingMilliseconds=0}.Valid);Assert.False(new GangDriveByOptions{VehicleModel="bad/model"}.Valid);}
    }
}
